import { chromium } from "playwright";
import { readFileSync, mkdirSync, readdirSync, renameSync, rmSync, writeFileSync } from "node:fs";
import { scenes } from "./scenes.mjs";
const D = JSON.parse(readFileSync("durations.json", "utf8"));
import { pathToFileURL } from "node:url"; import { resolve } from "node:path";
const STORY = pathToFileURL(resolve("story-engine.html")).href;
const W = 1280, H = 720, GAP = 700, MIN_PROOF = 4.2;
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
rmSync("raw", { recursive: true, force: true }); mkdirSync("raw", { recursive: true });
const browser = await chromium.launch({ executablePath: "C:/Users/DELL/AppData/Local/ms-playwright/chromium-1243/chrome-win64/chrome.exe" });
const ctx = await browser.newContext({ viewport: { width: W, height: H }, recordVideo: { dir: "raw", size: { width: W, height: H } } });
const t0 = Date.now(); const now = () => Date.now() - t0;
const page = await ctx.newPage(); page.setDefaultTimeout(60000);
async function smoothScrollTo(y, ms) {
  await page.evaluate(async ({ y, ms }) => {
    const start = window.scrollY, dist = y - start, t = performance.now();
    await new Promise((res) => { const step = (n) => { const p = Math.min(1, (n - t) / ms), e = p < .5 ? 2 * p * p : 1 - Math.pow(-2 * p + 2, 2) / 2; window.scrollTo(0, start + dist * e); p < 1 ? requestAnimationFrame(step) : res(); }; requestAnimationFrame(step); });
  }, { y, ms });
}
async function scrollToText(txt, ms = 1400) {
  const target = txt.startsWith("text=")
    ? await page.evaluate((t) => { const el = [...document.querySelectorAll("h1,h2,h3,.compare-src,.method-label")].find((e) => e.textContent.includes(t)); return el ? el.getBoundingClientRect().top + window.scrollY - 90 : null; }, txt.slice(5))
    : await page.evaluate((s) => { const el = document.querySelector(s); return el ? el.getBoundingClientRect().top + window.scrollY - 70 : null; }, txt);
  if (target != null) await smoothScrollTo(Math.max(0, target), ms);
}
const marks = [], cuts = [];
for (const s of scenes) {
  const a = D[s.id + "a"], b = D[s.id + "b"];
  // ---- story ----
  let sceneStart = now();
  await page.goto(STORY, { waitUntil: "load" });
  await page.evaluate(([n, c, d]) => window.init(n, c, d), [s.anim, a.cues, a.dur]);
  await sleep(250);
  if (now() - 300 > sceneStart) cuts.push([sceneStart, now() - 200]);
  await page.evaluate(() => window.start());
  marks.push({ id: s.id + "a", atMs: now() });
  const t1 = Date.now();
  await sleep(a.dur * 1000 + 300);
  if (!s.proof) { await sleep(GAP); continue; }
  // ---- proof ----
  sceneStart = now();
  const p = s.proof;
  await page.goto(p.url, { waitUntil: "domcontentloaded" }).catch(() => {});
  await sleep(1800);
  if (now() - 400 > sceneStart) cuts.push([sceneStart, now() - 400]);
  if (p.check) {
    await page.click("#checkBtn"); await sleep(800);
    const cs = now();
    await page.waitForSelector("#results .lookup-body", { timeout: 170000 });
    await sleep(400);
    if (now() - 300 > cs) cuts.push([cs, now() - 300]);
    const txt = await page.innerText("#results");
    if (/saved verdict|not answering/i.test(txt)) console.log("WARNING snapshot fallback", s.id);
  }
  const ps = Date.now();
  marks.push({ id: s.id + "b", atMs: now() });
  if (p.scroll) await scrollToText(p.scroll, 1300);
  if (p.check) { await sleep(1500); const h = await page.evaluate(() => document.documentElement.scrollHeight - innerHeight); await smoothScrollTo(Math.min(h, 800), 2200); }
  if (p.scrollPage) { await sleep(1200); const h = await page.evaluate(() => document.documentElement.scrollHeight - innerHeight); await smoothScrollTo(Math.min(h, 1400), Math.max(2000, b.dur * 1000 - 2500)); }
  const hold = Math.max(b.dur, MIN_PROOF) * 1000 - (Date.now() - ps);

