  const p = await ctx.newPage(); p.setDefaultTimeout(60000);
  const shot = async (name) => { await p.screenshot({ path: V + name }); console.log("saved", name); };
  const html = async (h, name) => { await p.setContent(h); await shot(name); };
  const cap = fs.readFileSync(R + "captured_at_utc.txt", "utf8").trim();

  // 1 wrong answers, real captured text
  for (const [n, f, lab] of [["01a_clerk_malformed_request_wrong_answer.png", "clerk_request1_malformed.txt", "A broken request (cut-off JSON)"], ["01b_clerk_unknown_order_wrong_answer.png", "clerk_request2_unknown_order.txt", "An order id that does not exist"]]) {
    let t = esc(fs.readFileSync(R + f, "utf8").trim());
    t = t.replace(/(HTTP\/1\.1 200 OK)/, '<span class="r">$1</span>').replace(/(\{&quot;|\{&amp;quot;|\{"order_id.*)/, '<span class="a">$1</span>');
