  const L = JSON.parse(fs.readFileSync(R + "signed_links.json", "utf8"));
  for (const [k, lab] of [["fix1_83", "Fix 1"], ["fix2_100", "Fix 2"], ["clerk_before_75", "Clerk before"]]) {
