    await shot(`02_${k}_signed_report_live_page.png`);
    const j = JSON.parse(fs.readFileSync(R + `signed_${k}.json`, "utf8")); const r = j.report;
    const col = r.silentWrongCount ? "r" : "g";
    const body = `<div style="font-size:30px;color:#9aa0a6;margin-bottom:10px">${lab} &nbsp;|&nbsp; signed by StressProof &nbsp;|&nbsp; valid: ${j.valid} &nbsp;|&nbsp; target ${esc(j.target)}</div>
<div style="display:flex;gap:90px;align-items:flex-end;margin:20px 0 30px"><div><div class="d" style="font-size:28px">score</div><div class="big ${col}">${j.score}</div></div>
<div><div class="d" style="font-size:28px">verdict</div><div class="big ${col}" style="font-size:90px">${esc(j.verdict)}</div></div>
<div><div class="d" style="font-size:28px">silentWrongCount (quiet wrong answers)</div><div class="big ${col}">${r.silentWrongCount}</div></div></div>
<pre style="font-size:28px" class="d">"verdictReason": "${esc(r.verdictReason)}"\n"probesRunSummary": "${esc(r.probesRunSummary.slice(0, 230))}..."\n"probesCompleted": ${r.probesCompleted}   "probesScorable": ${r.probesScorable}   "unclassifiedCount": ${r.unclassifiedCount}</pre>`;
    await html(wrap("<b>Signed report excerpt</b>", body, `Fields copied from the live signed report (fetched ${cap}); file: clips/raw/signed_${k}.json. The full report opens at the saved link in evidence\\scorecard.json.`), `02z_${k}_signed_report_zoom.png`);
  }
  // 3 PR #4, repo page
  await p.goto("https://github.com/Sireadell/suture/pull/4", { waitUntil: "load" }); await p.waitForTimeout(2500); await shot("03_pr4_page.png");
  await p.goto("https://github.com/Sireadell/suture", { waitUntil: "load" }); await p.waitForTimeout(2500); await shot("07_repo_page.png");
  // 4 entire
  const w = esc(fs.readFileSync(R + "entire_why_clerk2_line36.txt", "utf8").trim());
  await html(wrap("<b>Terminal</b> &nbsp; entire why targets/clerk2/app.py:36", `<pre class="a" style="font-size:30px;margin-bottom:24px">$ entire why targets/clerk2/app.py:36</pre><pre>${w}</pre>`, `Real output of the Entire CLI 0.11.4 run on ${cap} (UTC). Text re-drawn on a dark page, content unchanged.`), "04_entire_why_clerk2_line36.png");
  // 7 score table from files
  const rows = [];
  const rd = (f) => JSON.parse(fs.readFileSync("C:/Users/DELL/suture/evidence/" + f, "utf8").replace(/^\uFEFF/, ""));
  const sc = rd("scorecard.json"); const c2b = rd("before_clerk2_v1.json").report, c2a = rd("after_clerk2_v2.json").report;
  const T = [["Clerk (refund agent)", sc.before_score, sc.before_silent_wrong, 100, 0, "a quiet wrong answer fixed"], ["Notes agent", sc.notes.before_score, sc.notes.before_silent_wrong, sc.notes.after_score, sc.notes.after_silent_wrong, "a quiet wrong answer fixed"], ["Clerk2 (second refund agent)", c2b.score, c2b.silentWrongCount, c2a.score, c2a.silentWrongCount, "4 loud crashes fixed (no quiet failure)"]];
  const tb = T.map((r) => `<tr><td>${r[0]}</td><td class="r">${r[1]}</td><td>${r[2]}</td><td class="g">${r[3]}</td><td>${r[4]}</td><td class="d" style="font-size:28px">${r[5]}</td></tr>`).join("");
  await html(wrap("<b>Three agents</b> &nbsp; signed StressProof scores before and after", `<table><tr><th>Agent</th><th>Score before</th><th>Quiet wrong before</th><th>Score after</th><th>Quiet wrong after</th><th>Kind of fault</th></tr>${tb}</table>`, "Numbers read from evidence\\scorecard.json (Clerk, Notes), before_clerk2_v1.json and after_clerk2_v2.json (Clerk2). 100 means every check that could be judged passed (Clerk: 6 of 12 could be judged)."), "08_score_table_three_agents.png");
  console.log(JSON.stringify(T));
  await b.close();
})();
EOF
