// Builds the cut from stills + per-beat voice. Usage: node cut.mjs <voicedir> <beatsmap.json> <outprefix> [LABEL]
// beatsmap: { "A": ["P1.png", ...], ... } files are in ../clips. Outputs <outprefix>_silent.mp4 (no voice), <outprefix>.mp4 (voice) and <outprefix>_captioned.mp4 + .srt
import fs from "fs"; import { execSync } from "child_process";
const [, , vdir, mapf, outp, label] = process.argv;
const root = "C:/Users/DELL/hackathons/neathack/video/";
const W = root + "video-build/work_" + outp + "/"; fs.mkdirSync(W, { recursive: true });
const beats = JSON.parse(fs.readFileSync(vdir + "/beats.json", "utf8"));
const map = JSON.parse(fs.readFileSync(mapf, "utf8"));
const GAP = 0.7; const sh = (c) => execSync(c, { stdio: ["ignore", "pipe", "pipe"] }).toString();
const ts = (t) => { const h = Math.floor(t / 3600), m = Math.floor(t % 3600 / 60), s = t % 60; return `${String(h).padStart(2, "0")}:${String(m).padStart(2, "0")}:${s.toFixed(3).padStart(6, "0").replace(".", ",")}`; };
const vt = (s) => { const [a, b, c] = s.split(/[:.]/).length === 4 ? s.split(/[:.]/) : ["0", ...s.split(/[:.]/)]; return 0; };
const parseVtt = (f) => { const t = fs.readFileSync(f, "utf8").replace(/\r/g, ""); const cues = []; for (const blk of t.split(/\n\n+/)) { const m = blk.match(/(\d+):(\d+):([\d.]+) --> (\d+):(\d+):([\d.]+)\n([\s\S]+)/); if (m) cues.push({ s: +m[1] * 3600 + +m[2] * 60 + +m[3], e: +m[4] * 3600 + +m[5] * 60 + +m[6], t: m[7].replace(/\n/g, " ").trim() }); } return cues; };
let off = 0, srt = "", n = 0, list = "", slist = "";
for (const b of beats) {
  const imgs = map[b.id]; const dur = b.dur + GAP; const each = dur / imgs.length; const parts = [];
  imgs.forEach((im, i) => {
    const fr = Math.round(each * 25); const f = `${W}${b.id}${i}.mp4`;
    sh(`ffmpeg -y -loglevel error -loop 1 -i "${root}clips/${im}" -vf "scale=1920:1080:force_original_aspect_ratio=decrease,pad=1920:1080:(ow-iw)/2:(oh-ih)/2:color=0x0A0B0C,zoompan=z='min(zoom+0.0005,1.10)':d=${fr}:s=1280x720:fps=25,format=yuv420p" -frames:v ${fr} -c:v libx264 -preset veryfast "${f}"`);
    parts.push(f);
  });
  fs.writeFileSync(`${W}${b.id}.txt`, parts.map(p => `file '${p}'`).join("\n"));
  const vid = `${W}${b.id}_v.mp4`; sh(`ffmpeg -y -loglevel error -f concat -safe 0 -i ${W}${b.id}.txt -c copy "${vid}"`);
  const seg = `${W}${b.id}.mp4`;
  sh(`ffmpeg -y -loglevel error -i "${vid}" -i "${vdir}/${b.id}.mp3" -filter_complex "[1:a]aresample=44100,apad=pad_dur=${GAP}[a]" -map 0:v -map "[a]" -t ${dur} -c:v copy -c:a aac -ar 44100 -ac 1 "${seg}"`);
  const sil = `${W}${b.id}_s.mp4`; sh(`ffmpeg -y -loglevel error -i "${vid}" -an -c:v copy "${sil}"`);
  list += `file '${seg}'\n`; slist += `file '${sil}'\n`;
  for (const c of parseVtt(`${vdir}/${b.id}.vtt`)) { n++; srt += `${n}\n${ts(off + c.s)} --> ${ts(off + c.e)}\n${c.t}\n\n`; }
  off += dur;
}
fs.writeFileSync(W + "list.txt", list); fs.writeFileSync(W + "slist.txt", slist);
const O = root + "video-build/";
sh(`ffmpeg -y -loglevel error -f concat -safe 0 -i ${W}slist.txt -c copy ${O}${outp}_silent.mp4`);
sh(`ffmpeg -y -loglevel error -f concat -safe 0 -i ${W}list.txt -c copy ${O}${outp}.mp4`);
fs.writeFileSync(O + outp + ".srt", srt);
// captioned: pad to 1280x810 and burn the caption bar (run in O so the subtitle path is relative)
const lab = label ? `,drawtext=text='${label}':x=12:y=8:fontsize=18:fontcolor=0xC97A3D:box=1:boxcolor=0x0A0B0C@0.7:boxborderw=6` : "";
